local _, ns = ...
local E = ns.DB.entries
E["npc:loganaar"] = {t="npc",n="Loganaar",z="moonglade",s="Loganaar is a night elf druidic instructor residing in the haven of Nighthaven in Moonglade. Dedicated to guiding initiates from both the Alliance and the Horde, he instructs young druids as they attune to the wild and prepare for the call of the Emerald Dream.",h="Loganaar is a night elf druidic instructor residing in the haven of Nighthaven in Moonglade.",sec={{t="Keeper of the Sacred Art",b="Situated amidst the serene boughs of Nighthaven, Loganaar serves as a primary mentor to newly initiated druids traveling to Moonglade. Regardless of whether an initiate hails from Darnassus or Thunder Bluff, Loganaar provides guidance in balance, shape-shifting, and reverence for nature. He reminds his students that even within cold stone and unfamiliar lands, true tranquility must be found within oneself. He also acts as a welcoming guide for those journeying deeper into the Cenarion Circle's affairs, sending promising students to wanderers like Torwa Pathfinder in Un'Goro Crater or deeper into ancient woodland rites.",sp=0},{t="The Call of the Dream",b="Beyond fundamental spellcraft, Loganaar prepares students for the ultimate destiny shared by Kalimdor's traditional protectors: the deep slumber of the Emerald Dream. He instructs initiates on the sacred connection between Azeroth's primal spirit realm and the waking world, reminding them that true mastery will one day require hibernating for centuries to walk among nature's purest, unblemished forms under the guidance of the demigods.",sp=0}},faq={{q="Who is Loganaar?",a="Loganaar is a night elf druid trainer based in Nighthaven, the central settlement of Moonglade. He welcomes druids of all backgrounds to train in their arts and introduces them to the deeper traditions of the Cenarion Circle.",al={"loganaar npc","who is loganaar","loganaar lore"}},{q="Does Loganaar train Horde druids?",a="Yes. Moonglade is sacred, neutral ground overseen by the Cenarion Circle. As a member of the Circle, Loganaar sets aside the conflict between the Alliance and Horde to instruct tauren and night elf druids alike.",al={"can tauren train at loganaar","loganaar horde","druid trainer moonglade horde"}},{q="What does Loganaar teach about the Emerald Dream?",a="Loganaar teaches that every true druid will eventually feel the pull of the Emerald Dream. He explains that walking among its uncorrupted forms during a long, deep hibernation is where a druid's ultimate training takes place.",al={"loganaar dream","emerald dream quote"}},{q="Where does Loganaar send seasoned druids?",a="As druids grow in experience, Loganaar directs them outward to observe and mend Azeroth's primal ecosystems. Among his tasks, he sends seasoned disciples to assist naturalists such as Torwa Pathfinder in the untamed wilderness of Un'Goro Crater.",al={"loganaar quests","torwa pathfinder quest loganaar"}}},ang={["class:Druid"]="For druids of both Darnassus and Thunder Bluff, Loganaar is one of the earliest mentors met upon teleporting to Moonglade, providing advanced training and spiritual counsel.",["race:NightElf"]="Loganaar reflects the ancient traditions of the Kaldorei druids who spent millennia communing with nature and entering the Emerald Dream under Malfurion Stormrage."},kw={"cenarion circle","druid trainer","emerald dream","loganaar","moonglade","nighthaven"},rel={"subzone:nighthaven","zone:moonglade","topic:druid","topic:emerald-dream","npc:torwa-pathfinder","topic:cenarius","topic:night-elf"},src={"Loganaar"}}
E["npc:remulos"] = {t="npc",n="Remulos",z="moonglade",s="Keeper Remulos is a demigod son of Cenarius and the venerable protector of Moonglade. Alongside Archdruid Fandral Staghelm and Hamuul Runetotem, he helps guide the Cenarion Circle in the absence of his fallen father and the sleeping Malfurion Stormrage. Unlike Staghelm, Remulos prioritizes the broader balance of nature over night elven isolationism.",h="Keeper Remulos is a demigod son of Cenarius and the venerable protector of Moonglade.",sec={{t="Lord of the Sacred Grove",b="Keeper Remulos is an immortal keeper of the grove, bearing the lower body of a great stag and the antlered torso of an ancient dryad-father. He watches over Moonglade, the sacred sanctuary of Azeroth's druids nestled north of Mount Hyjal. While Malfurion Stormrage remains trapped in the Emerald Dream, Remulos provides divine authority and counsel to the mortals of the Cenarion Circle. He remains deeply invested in healing Azeroth's scars, offering aid to druids pursuing their sacred rites around Lake Elune'ara.",sp=0},{t="A Rift in the Circle",b="Remulos frequently finds himself at ideological odds with Archdruid Fandral Staghelm. While Staghelm champions night elven supremacy and sought to restore their lost immortality through Teldrassil, Remulos vehemently opposed the planting of the new World Tree as an act of hubris. Defying Staghelm's isolationist faction, Remulos welcomed Hamuul Runetotem and the tauren into the Cenarion Circle, sharing nature's closely guarded mysteries with their shamans-turned-druids to restore the land collectively.",sp=0}},faq={{q="Who is Keeper Remulos?",a="He is an immortal son of Cenarius and brother to the fallen Zaetar. Remulos resides in the Shrine of Remulos in Moonglade, serving as the guardian of the grove and a senior leader of the Cenarion Circle.",al={"remulos lore","who is remulos","keeper remulos background"}},{q="Why does Remulos support the tauren druids?",a="Remulos views nature's balance as transcending mortal racial divides. Recognizing the tauren's deep bond with the Earth Mother, Remulos overrode Archdruid Fandral Staghelm's objections and welcomed Archdruid Hamuul Runetotem and his people into the Cenarion Circle.",al={"remulos tauren","why do tauren have druids","remulos hamuul"}},{q="What is Remulos's opinion on Teldrassil?",a="Remulos vehemently opposed the creation of Teldrassil. He saw the planting of the new World Tree as a selfish effort by night elves to reclaim their lost immortality, rather than an act performed for the genuine healing of Azeroth.",al={"remulos world tree","remulos fandral tree"}},{q="What relation does Remulos have to Maraudon?",a="His brother Zaetar ventured into Desolace and mated with Princess Theradras, creating the centaur race before dying. Remulos warned Zaetar against the cursed union, and he finds peace only when travelers help bring rest to Zaetar's lingering spirit.",al={"remulos zaetar","remulos theradras","remulos brother"},sp=1}},ang={["class:Druid"]="Every druid, whether night elf or tauren, journeys to Moonglade to commune with Keeper Remulos and receive guidance on mastering animal forms and sacred trials.",["race:Tauren"]="Tauren druids revere Remulos for defying Fandral Staghelm and granting their people entry and full teaching within the Cenarion Circle."},kw={"cenarion circle","cenarius","fandral staghelm","grove","hamuul runetotem","moonglade","remulos","zaetar"},rel={"topic:cenarion-circle","topic:cenarius","zone:moonglade","npc:fandral-staghelm","quest:1489","npc:malfurion-stormrage","subzone:lake-elune-ara","topic:druid"},src={"Remulos"}}
E["subzone:lake-elune-ara"] = {t="subzone",n="Lake Elune'ara",z="moonglade",s="Lake Elune'ara is the shimmering, sacred body of water that occupies the heart of Moonglade. Revering the Moon Goddess Elune, the lake serves as a place of spiritual reflection for the Cenarion Circle, though deep within its murky floor lies the dormant, corrupted demigod Omen.",h="Lake Elune'ara is the shimmering, sacred body of water that occupies the heart of Moonglade.",sec={{t="Heart of the Sacred Vale",b="Framed by the moonlit groves of Moonglade, Lake Elune'ara provides serene waters said to be blessed by the White Lady herself. The lake lies at the spiritual center of the druidic haven, bordered by Nighthaven to the north and the shrine grounds of the Cenarion Circle. Initiates have long plumbed its tranquil depths to retrieve long-lost relics, attuning themselves to the currents of nature as they seek harmony with the land.",sp=0},{t="The Slumber of Omen",b="Despite the tranquility on the surface, ancient peril rests beneath the gentle ripples. Centuried legends speak of the two-headed wolf demigod Omen, a revered ancient corrupted by the Burning Legion during the War of the Ancients. Defeated and cast into the lake bed long ago, Omen slumbers deep below the dark waters, an enduring reminder of nature's wounds.",sp=0}},faq={{q="What is Lake Elune'ara?",a="It is the large, sacred lake dominating the center of Moonglade. Revered by night elves and druids, it is named after the Moon Goddess Elune and surrounded by the sanctuaries of the Cenarion Circle.",al={"lake eluneara","moonglade lake","where is lake eluneara"}},{q="What lurks at the bottom of the lake?",a="The fallen demigod Omen sleeps in the dark depths of the lake. Once a noble ancient, he was driven mad by the Burning Legion during the ancient war and cast into the lake upon his defeat.",al={"what is inside lake elune'ara","omen in moonglade","monster in lake"}},{q="Why do druids come to this lake?",a="The lake is deeply connected to druidic trials and communing with the spirits of nature. Young druids often delve into its waters searching for sacred relics as part of their rites of passage.",al={"druid quest lake","aquatic form lake"}}},ang={["class:Druid"]="The lake is an integral site for druidic rituals and testing, holding sacred relics within its deep waters that aid initiates on their path.",["race:NightElf"]="Named for Elune, the lake represents a place of divine peace and historical memory of the War of the Ancients."},kw={"cenarion circle","dark waters","elune","lake elune'ara","moonglade","nighthaven","omen"},rel={"zone:moonglade","topic:druid","topic:elune","quest:31","topic:emerald-dream","quest:5921"},src={"Lake Elune'ara"}}
E["subzone:nighthaven"] = {t="subzone",n="Nighthaven",z="moonglade",s="Nighthaven is a secluded settlement resting on the northern shores of Lake Elune'ara in Moonglade. Serving as the heart of the Cenarion Circle, it is a haven where night elf and tauren druids study together in peace beyond the factional wars of Azeroth.",h="Nighthaven is a secluded settlement resting on the northern shores of Lake Elune'ara in Moonglade.",sec={{t="A Sanctuary of the Cenarion Circle",b="Built with traditional night elf architecture along the calm shores of Lake Elune'ara, Nighthaven is a tranquil retreat largely secluded from the outside world. Here, moonwells cast a gentle glow over groves and halls dedicated to preserving the natural balance. As the primary enclave of the Cenarion Circle, it provides trainers, herbalists, and specialized suppliers for druidic initiates. The settlement maintains a strict neutrality, welcoming practitioners regardless of whether their home loyalties lie with the Alliance or the Horde.",sp=0},{t="Ancient History and Sacred Gatherings",b="Nighthaven's peace has been tested throughout history. Centuries after the War of the Ancients, champions gathered here to confront the enraged demigod Omen, driving him beneath the depths of Lake Elune'ara. The village also opens its secluded borders during the Lunar Festival, welcoming pilgrims from all over Azeroth to honor the ancestors and celebrate under Elune's watchful gaze.",sp=0}},faq={{q="Who rules or oversees Nighthaven?",a="Nighthaven is administered by the Cenarion Circle under the guidance of Keeper Remulos and senior druids such as Loganaar. It exists as an independent, neutral sanctuary rather than a territory of the night elven government.",al={"who runs nighthaven","nighthaven leaders","who is in charge here"}},{q="Can non-druids visit Nighthaven?",a="Yes. Non-druids can reach Moonglade through the Timbermaw tunnels or use the public flight masters elsewhere in the valley, then travel to Nighthaven. The village's own flight masters serve only druids.",al={"can non druids go to nighthaven","how do non druids get here"}},{q="Why are night elves and tauren living together peacefully here?",a="The Cenarion Circle is committed to healing nature and the Emerald Dream above all faction politics. Members take vows of neutrality while within Moonglade, putting aside Alliance and Horde rivalries to study druidism as equals.",al={"why no fighting here","why are tauren allowed here","horde alliance peace"}},{q="What flight routes are available from Nighthaven?",a="Exclusive Cenarion flight masters offer direct travel for druids: hippogryphs provide passage back to Rut'theran Village for the Alliance, while wind riders carry Horde druids back to Thunder Bluff.",al={"nighthaven flight masters","where can i fly from here"}}},ang={["class:Druid"]="Nighthaven is your spiritual home away from home. Through the Teleport: Moonglade ability, it provides immediate access to your order's mentors, animal form trials, and unique flight connections to Rut'theran Village or Thunder Bluff.",["profession:Herbalism"]="Nighthaven is a peaceful place to consult herbalism trainers among the tranquil groves of Moonglade."},kw={"cenarion circle","druid","lake elune'ara","loganaar","lunar festival","moonglade","nighthaven","remulos"},rel={"zone:moonglade","topic:cenarion-circle","subzone:lake-elune-ara","npc:remulos","npc:loganaar","topic:druid","subzone:rut-theran-village","zone:thunderbluff"},src={"Nighthaven"}}
E["subzone:stormrage-barrow-dens"] = {t="subzone",n="Stormrage Barrow Dens",z="moonglade",s="The Stormrage Barrow Dens are an ancient subterranean sanctuary carved beneath the sacred valley of Moonglade. Named for Malfurion Stormrage, these quiet earth-hewn chambers serve as a dedicated resting place where druids enter long, restorative slumbers to wander the Emerald Dream.",h="The Stormrage Barrow Dens are an ancient subterranean sanctuary carved beneath the sacred valley of Moonglade.",sec={{t="Chambers of the Slumbering",b="Barrow dens serve as sacred havens throughout night elven lands, providing druids a safe subterranean refuge where their physical bodies can lie undisturbed during lengthy immersions in the Emerald Dream. The Stormrage Barrow Dens are particularly esteemed within the sacred realm of Moonglade. Named in honor of Archdruid Malfurion Stormrage, these winding earthen halls hold both ancient reverence and quiet vigil. While some druids like Clintar Dreamwalker still slumber safely within its alcoves, the absence of the great Archdruid himself casts a somber shadow over the hollowed roots and peaceful glowing lanterns.",sp=0},{t="Echoes of the Third War",b="During the desperate days of the Third War, these dens stood on the brink of total ruin. The dreadlord Tichondrius and the Burning Legion's forces sought to eradicate the sleeping druids before they could rally. High Priestess Tyrande Whisperwind fought her way through invading demons and hostile corrupted wildlife deep into these earthen tunnels to blow the Horn of Cenarius, waking Malfurion Stormrage in the nick of time. Following Archimonde's defeat at Mount Hyjal, Malfurion returned to Moonglade to commune with the spirits, but his essence has once more drifted into the Dream, leaving his brethren to watch over these sacred earthen depths.",sp=0}},faq={{q="What is the purpose of the Stormrage Barrow Dens?",a="Barrow dens provide protected, tranquil subterranean sanctuaries for night elf druids. While their minds and spirits traverse the vast pathways of the Emerald Dream, their mortal bodies remain motionless and defenseless for months or years, requiring a quiet and sheltered retreat to rest safely under the vigil of their brethren.",al={"what are the barrow dens for","why sleep in barrow dens","stormrage barrow dens purpose"}},{q="Is Malfurion Stormrage currently inside these dens?",a="Malfurion Stormrage famously rested in the barrow dens during the Third War before Tyrande awakened him. After the war concluded and debates arose regarding planting a new World Tree, he entered a deep communion with nature and his spirit became lost within the Emerald Dream, leaving the Cenarion Circle to tend to his resting place.",al={"where is malfurion","is malfurion in the barrow dens","can i find malfurion here"}},{q="Who is currently sleeping within these dens?",a="Among the druids resting within the dens is Clintar Dreamwalker, who lies in a deep, dream-bound slumber beneath the earth while his spirit journeys through the ethereal pathways of nature.",al={"who is asleep here","clintar dreamwalker","sleeping druids moonglade"}},{q="What happened to this place during the Third War?",a="During the Third War, the dreadlord Tichondrius and the demonic forces of the Burning Legion invaded the barrow dens in an effort to slaughter the slumbering night elf druids. High Priestess Tyrande Whisperwind led an assault into the depths, fighting through demonic forces to sound the Horn of Cenarius and awaken Malfurion.",al={"third war barrow dens","tichondrius attack moonglade","tyrande awakening of stormrage"}}},ang={["class:Druid"]="For druids of both races, the Stormrage Barrow Dens represent the hallowed heart of Cenarion heritage, demonstrating the traditional earth-sheltered sanctuaries where elder practitioners slip between Azeroth and the Emerald Dream.",["race:NightElf"]="This hollow holds profound historical weight for the Kaldorei, remembering both the millennia-long vigilance of their slumbering men and Tyrande Whisperwind's perilous descent to awaken Malfurion against the Burning Legion."},kw={"barrow den","cenarion circle","clintar dreamwalker","emerald dream","malfurion","moonglade","stormrage barrow dens"},rel={"zone:moonglade","npc:malfurion-stormrage","topic:emerald-dream","topic:cenarion-circle","topic:druid","npc:tyrande-whisperwind","topic:third-war","topic:night-elf"},src={"Stormrage Barrow Dens"}}
E["subzone:timbermaw-hold"] = {t="subzone",n="Timbermaw Hold",z="moonglade",s="Timbermaw Hold is a fortified subterranean network of tunnels that links Felwood, Moonglade, and Winterspring. It serves as the stronghold for the Timbermaw furbolgs, one of the last tribes to resist the demonic corruption plaguing northern Kalimdor.",h="Timbermaw Hold is a fortified subterranean network of tunnels that links Felwood, Moonglade, and Winterspring.",sec={{t="A Sanctuary Amidst Decay",b="Carved deep into the mountain roots between Felwood, Moonglade, and Winterspring, Timbermaw Hold stands as a desperately guarded bastion. While neighboring furbolg tribes fell to the foul taint of the Burning Legion during the Third War, the Timbermaw clan weathered the nightmare within these stone corridors. Though safe beneath the earth, they were forced to watch their beloved forests warp into corrupted mockeries. Extremely protective and deeply suspicious of outsiders, the furbolgs guard every tunnel entrance fiercely, expecting violence from anyone wandering in from the infected woods.",sp=0},{t="Crossroads of the North",b="Beyond its role as a tribal sanctuary, Timbermaw Hold is the only direct mountain highway connecting the tainted lowlands of Felwood, the sacred sanctuary of Moonglade, and the frozen expanse of Winterspring. Outsiders who wish to pass through without being torn apart by tribal sentries must prove their goodwill. Those who demonstrate their opposition to the region's corrupted furbolg clans find the Timbermaw to be steadfast allies willing to share their ancient shamanic knowledge and leathercrafting traditions.",sp=0}},faq={{q="Why do the furbolgs in Timbermaw Hold attack visitors?",a="The Timbermaw tribe is naturally distrustful of outsiders after seeing their neighboring kin succumb to the Burning Legion's corruption. Fearing that strangers will confuse them with feral, demonic furbolgs—or bring the taint into their home—they attack anyone approaching their tunnels until an outsider proves their peaceful intentions.",al={"why are timbermaw hostile","timbermaw attacking me","how to get timbermaw friendly"}},{q="Which zones does Timbermaw Hold connect?",a="The main cavern branches into three primary exits: northern Felwood to the southwest, the tranquil haven of Moonglade to the north, and the frosty valleys of Winterspring to the east. A walled-off gate also sits in northern Azshara.",al={"timbermaw hold tunnel destinations","where does timbermaw hold lead","timbermaw exits"}},{q="How did the Timbermaw survive the Legion's taint?",a="While the forests of Felwood withered under demonic fel energy, the Timbermaw tribe took shelter deep within their mountain caverns. By sealing themselves inside the hold during the height of the demonic invasion, they managed to preserve their minds and sacred shamanic ways while neighboring clans fell to madness.",al={"why are timbermaw uncorrupted","timbermaw not corrupted"}},{q="What is the sealed wooden door inside the hold?",a="Deeper in the tunnels sits a round wooden barrier blocking a side cavern. Its exact purpose is uncertain, though travelers theorize it seals off older tunnel complexes leading toward the Barrow Deeps or other ancient subterranean chambers under Mount Hyjal.",al={"blocked door in timbermaw hold","timbermaw hold locked gate"}}},ang={["class:Druid"]="The hold serves as a critical mountain thoroughfare between your sacred sanctuary in Moonglade and the wounded wilderness of Felwood, where furbolg spirits desperately need cleansing.",["class:Shaman"]="The Timbermaw have fiercely maintained their uncorrupted spiritual traditions and healing rituals despite the fel corruption festering directly outside their cave gates."},kw={"felwood","furbolg","moonglade","timbermaw","timbermaw hold","tunnel","winterspring"},rel={"topic:furbolg","zone:felwood","zone:winterspring","zone:moonglade","topic:burning-legion","zone:azshara","subzone:irontree-woods"},src={"Timbermaw Hold"}}
E["zone:moonglade"] = {t="zone",n="Moonglade",z="moonglade",s="Moonglade is an ancient, secluded forest valley nestled high in northern Kalimdor, revered as the sacred heartland of druidism and the home of the Cenarion Circle. Sheltered beneath perpetual twilight and untouched by mortal corruption, it is a neutral haven where night elf and tauren practitioners study nature side by side. For non-druids, reaching this highland sanctuary requires braving the hazardous mountain tunnel of Timbermaw Hold.",h="Moonglade is an ancient, secluded forest valley nestled high in northern Kalimdor, revered as the sacred...",sec={{t="Sacred Twilight",b="Ringed by sheer mountains north of Felwood and Winterspring, Moonglade exists in a state of eternal, serene night under the soft glow of Elune's moon. At its center lies Lake Elune'ara, a deep, tranquil body of water held sacred since the dawn of kaldorei civilization. The glade remained unmarred by the Burning Legion during both ancient invasions and the recent Third War, shielded by the vigilant demigod Cenarius and his offspring. Today, under the stewardship of Keeper Remulos, the valley serves as a peaceful redoubt where nature's balance is preserved free from factional conflict.",sp=0},{t="Seat of the Circle",b="Moonglade is the headquarters of the Cenarion Circle, founded millennia ago by Malfurion Stormrage during the War of the Satyr. In the lakeside village of Nighthaven, ancient traditions guide druidic instruction. Following the Third War, the Circle took the historic step of welcoming tauren into their ranks, led by the teachings of Archdruid Hamuul Runetotem. In Moonglade, political loyalties to the Alliance or Horde are put aside; armed sentries enforce strict neutrality, ensuring that any violence between members meets swift justice.",sp=0},{t="The Barrow Dens and the Dream",b="South of Lake Elune'ara stand the ancient Stormrage Barrow Dens. For thousands of years, elven druids lay slumbering within these subterranean hollows, traversing the spirit realm of the Emerald Dream while their mortal bodies rested under constant vigil. It was here that Tyrande Whisperwind sounded the Horn of Cenarius to awaken Malfurion during the Third War. Even now, the dens remain intimately tied to the Dream, though strange, unsettling ripples have begun emerging from the deep tunnels as dark whispers trouble the Emerald realm.",sp=1}},faq={{q="How do non-druid travelers reach Moonglade?",a="Unless brought by ritual magic during seasonal events, travelers on foot must pass through Timbermaw Hold, a tunnel complex bridging upper Felwood, Winterspring, and Moonglade. The Timbermaw furbolgs fiercely guard this passage, requiring outsiders to prove their goodwill before granting safe conduct.",al={"how to get to moonglade","getting to moonglade","moonglade entrance"}},{q="Why can Horde and Alliance walk together peacefully here?",a="Moonglade is governed by the Cenarion Circle, an order dedicated entirely to nature rather than politics. The Moonglade Wardens stationed throughout Nighthaven enforce strict neutrality, immediately attacking anyone who initiates violence against those in good standing with the Circle.",al={"why is moonglade neutral","pvp in moonglade","can horde and alliance fight here"}},{q="What is the purpose of Nighthaven?",a="Nighthaven is the primary settlement in Moonglade, serving as the dwelling place and operational hub for the Cenarion Circle. It houses trainers, caretakers, and sanctuaries where both kaldorei and tauren druids confer on matters concerning the health of Azeroth's wild lands.",al={"nighthaven purpose","what is nighthaven","town in moonglade"}},{q="Who rules Moonglade in Malfurion Stormrage's absence?",a="Keeper Remulos, a powerful son of the demigod Cenarius, watches over Moonglade from the Shrine of Remulos. Working alongside senior circle members like Dendrite Starblaze, he tends to the sacred grounds and directs efforts to heal the world.",al={"leader of moonglade","who leads cenarion circle","who is remulos"}},{q="What rests beneath the Stormrage Barrow Dens?",a="The Barrow Dens are deep underground chambers where druids traditionally entered extended communion with the Emerald Dream. Deep wings of these chambers retain powerful conduits to the Dream, though recent disturbances suggest unsettling nightmares are beginning to stir inside.",al={"barrow dens lore","stormrage barrow dens purpose","where druids sleep"}},{q="Why do druids have special flight paths out of Nighthaven?",a="The hippogryph master Silva Fil'naveth and wind rider keeper Bunthen Plainswind offer dedicated transit directly to Rut'theran Village and Thunder Bluff solely for druids, ensuring the order can readily travel between their sacred grove and their racial homelands.",al={"nighthaven flight masters","druid flight master moonglade","free flights in moonglade"}}},ang={["class:Druid"]="Moonglade is your sacred home and sanctuary. Through your innate spiritual link, you can teleport here from anywhere across Azeroth to consult masters like Dendrite Starblaze, commune with great spirits, and master forms such as the aquatic form.",["race:Tauren"]="Your inclusion in the Cenarion Circle represents a historic revival of an ancient bond with Cenarius, championed by Hamuul Runetotem and respected across Moonglade despite ancient night elf seclusion.",["race:NightElf"]="For ten millennia, Moonglade was your people's spiritual heartland and the resting place of your sleeping archdruids, sheltered beneath the enduring blessing of Elune."},kw={"cenarion circle","dendrite starblaze","emerald dream","lake elune'ara","moonglade","nighthaven","remulos","stormrage barrow dens"},rel={"topic:cenarion-circle","topic:druid","npc:remulos","subzone:nighthaven","subzone:stormrage-barrow-dens","subzone:lake-elune-ara","topic:emerald-dream","subzone:timbermaw-hold"},src={"Moonglade"}}
